SourceCode.Declaration:
/// <summary>
/// Represents the business event that is triggered when a transfer order is received.
/// </summary>
/// <remarks>
/// This business event captures transfer order details from <c>InventTransferTable</c>
/// and exposes them through the <c>METTransferOrderReceivedBusinessEventsContract</c>.
/// </remarks>
[BusinessEvents(classStr(METTransferOrderReceivedBusinessEventsContract),
    "@MET:METTransferOrderReceivedEvent",
    "@MET:METTransferOrderReceivedEventDesc",
    ModuleAxapta::Inventory)]
public class METTransferOrderReceivedBusinessEvent extends BusinessEventsBase
{
    InventTransferTable transferTable;

}

Method.Source:
/// <summary>
/// Constructs a new <c>METTransferOrderReceivedBusinessEvent</c> business event from the specified transfer order.
/// </summary>
/// <param name="_transferTable">The <c>InventTransferTable</c> record to associate with the event.</param>
/// <returns>A new <c>METTransferOrderReceivedBusinessEvent</c> instance.</returns>
static public METTransferOrderReceivedBusinessEvent newFromInventTransferTable(InventTransferTable _transferTable)
{
    METTransferOrderReceivedBusinessEvent businessEvent = new METTransferOrderReceivedBusinessEvent();
    businessEvent.parmInventTransferTable(_transferTable);
    return businessEvent;
}

/// <summary>
/// Initializes a new instance of the <c>METTransferOrderReceivedBusinessEvent</c> class.
/// </summary>
private void new()
{
}

/// <summary>
/// Gets or sets the transfer order associated with this business event.
/// </summary>
/// <param name="_transferTable">The <c>InventTransferTable</c> record to set. If not provided, returns the current value.</param>
/// <returns>The current <c>InventTransferTable</c> record.</returns>
private InventTransferTable parmInventTransferTable(InventTransferTable _transferTable = transferTable)
{
    transferTable = _transferTable;
    return transferTable;
}

/// <summary>
/// Builds and returns the business event data contract for the transfer order received event.
/// </summary>
/// <returns>A new <c>METTransferOrderReceivedBusinessEventsContract</c> instance containing the event data.</returns>
[Wrappable(true), Replaceable(true)]
public BusinessEventsContract buildContract()
{
    return METTransferOrderReceivedBusinessEventsContract::newFromInventTransferTable(transferTable);
}
